def main():
    d = json.load(open(CAT, encoding='utf-8'))
    ms = d['motions']; have = {m['name']: m for m in ms}
    no = max(m.get('no', 0) for m in ms)
    for fx, ua, moments, use, tv, note in AY:
        name = 'fx-' + fx
        m = have.get(name)
        if not m:
            no += 1; m = {'name': name, 'no': no}; ms.append(m); have[name] = m
        m.update({'fx': fx, 'engine': 'fx', 'ua': ua, 'moments': moments, 'status': 'ready', 'use': use, 'quality': 4, 'rank': 2,
                  'group': GROUP, 'text': 'fx', 'text_vars': tv, 'note': CARD % fx + note})
    json.dump(d, open(CAT, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(f'{len(AY)} ay-* entries in the catalog')


if __name__ == '__main__':
    main()
